contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We need to receive refunds/transfers from C if it sends ETH to this contract
    receive() external payable {}

    // params:
    // whale - address to pass to constructor of C was already used by deployer; not needed
    // amount - the bet limit to set and send when wagering
    // difficulty - set difficulty (not used directly but we call AdjustDifficulty to avoid zero division)
    function run(uint256 amount, uint256 difficulty) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        // make sure this contract has enough balance to send the wager
        require(address(this).balance >= amount);

        // Open contract to public by calling OpenToThePublic as owner: the InvMutTest deployed C and is owner
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;

        // Set bet limit to 'amount'
        c.AdjustBetAmounts(amount); if (__ESBMC_reverted()) return;

        // Ensure difficulty non-zero so play's modulo is well-defined
        c.AdjustDifficulty(difficulty == 0 ? 1 : difficulty); if (__ESBMC_reverted()) return;

        // Place a wager by sending exactly 'amount'
        c.wager{value: amount}(); if (__ESBMC_reverted()) return;

        // After wagering, hasPlayerWagered(this) should be true
        bool afterWager = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        // attempt to play and record whether it reverted
        bool reverted;
        c.play(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After play: either the call reverted (so state unchanged), or the player's wager was cleared
        bool afterPlay = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted || !afterPlay);
    }
}

