pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount, uint256 difficulty) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        try c.OpenToThePublic() {} catch { return; }
        try c.AdjustBetAmounts(amount) {} catch { return; }
        try c.AdjustDifficulty(difficulty == 0 ? 1 : difficulty) {} catch { return; }
        try c.wager{value: amount}() {} catch { return; }
        bool afterWager;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { afterWager = __r; } catch { return; }
        bool reverted;
        try c.play() {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool afterPlay;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { afterPlay = __r; } catch { return; }
        assertTrue(reverted || !afterPlay);
    }

    function testFuzz_run(uint256 amount, uint256 difficulty) public {
        _run(amount, difficulty);
    }

    receive() external payable {}
}
